-- Generated from "SKU Master June 2026 values only (6).xlsx" (sheet "SKU"), 168 SKUs.
-- Paste into the Supabase SQL Editor. Upserts on item_code: existing SKUs are
-- overwritten with the sheet's values, new ones are inserted. Nothing is deleted.
-- ASIN (AMAZON) column in the sheet is skipped — sku_master has no such column.

on conflict (item_code) do update set
  item_description = excluded.item_description,
  group_name = excluded.group_name,
  sub_group = excluded.sub_group,
  series = excluded.series,
  sachet_count = excluded.sachet_count,
  case_pack = excluded.case_pack,
  alt_uom = excluded.alt_uom,
  unit_net_wt_g = excluded.unit_net_wt_g,
  unit_net_wt_oz = excluded.unit_net_wt_oz,
  unit_net_wt_lb = excluded.unit_net_wt_lb,
  carton_net_wt_kg = excluded.carton_net_wt_kg,
  carton_net_wt_lb = excluded.carton_net_wt_lb,
  gtin_upc_case_code = excluded.gtin_upc_case_code,
  unit_upc_code = excluded.unit_upc_code,
  shelf_life_months = excluded.shelf_life_months,
  unit_length_cm = excluded.unit_length_cm,
  unit_height_cm = excluded.unit_height_cm,
  unit_width_cm = excluded.unit_width_cm,
  unit_length_in = excluded.unit_length_in,
  unit_height_in = excluded.unit_height_in,
  unit_width_in = excluded.unit_width_in,
  unit_gross_wt_g = excluded.unit_gross_wt_g,
  unit_gross_wt_oz = excluded.unit_gross_wt_oz,
  case_cube_cuft = excluded.case_cube_cuft,
  case_cube_cbm = excluded.case_cube_cbm,
  case_length_cm = excluded.case_length_cm,
  case_height_cm = excluded.case_height_cm,
  case_width_cm = excluded.case_width_cm,
  case_length_in = excluded.case_length_in,
  case_height_in = excluded.case_height_in,
  case_width_in = excluded.case_width_in,
  case_gross_wt_lb = excluded.case_gross_wt_lb,
  case_gross_wt_kg = excluded.case_gross_wt_kg,
  pallet_length_in = excluded.pallet_length_in,
  pallet_width_in = excluded.pallet_width_in,
  pallet_height_in = excluded.pallet_height_in,
  pallet_ti = excluded.pallet_ti,
  pallet_hi = excluded.pallet_hi,
  pallet_cases_per_pallet = excluded.pallet_cases_per_pallet,
  updated_at = now();
